INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-01', 'owner', 'audio-itops-01', '01. High CPU Alert & Memory Leak Triage (IT Ops)', 'On-call bridge call between a NOC analyst and an SRE triaging a production CPU spike, heap dump capture, and safe rollback (~1 min, B1-B2).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-01-seg-1', 'lesson-audio-itops-01', 'owner', 0, 7.1, 'Hi Mark, sorry to wake you, but production web server three just crossed ninety percent CPU.', '[NOC] Chào Mark, xin lỗi đã đánh thức anh, nhưng máy chủ web production số ba vừa vượt ngưỡng 90% CPU.', 'production, crossed, ninety percent CPU', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-01-seg-2', 'lesson-audio-itops-01', 'owner', 7.1, 13.8, 'I am logging into the monitoring dashboard now; are customer requests starting to time out?', '[SRE] Tôi đang đăng nhập bảng điều khiển giám sát; yêu cầu của khách hàng có bắt đầu bị quá thời gian chờ không?', 'monitoring dashboard, time out', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-01-seg-3', 'lesson-audio-itops-01', 'owner', 13.8, 20.1, 'Yes, average latency jumped above two seconds, and memory usage keeps climbing without dropping.', '[NOC] Có, độ trễ trung bình nhảy vọt lên trên hai giây và mức dùng bộ nhớ cứ tăng liên tục không giảm.', 'average latency, memory usage, climbing', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-01-seg-4', 'lesson-audio-itops-01', 'owner', 20.1, 25.6, 'That looks like a classic memory leak triggering heavy garbage collection cycles.', '[SRE] Nghe giống lỗi rò rỉ bộ nhớ kinh điển gây ra các chu kỳ thu gom rác nặng nề.', 'memory leak, garbage collection cycles', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-01-seg-5', 'lesson-audio-itops-01', 'owner', 25.6, 31.5, 'Should I restart the application service immediately to bring the CPU back down?', '[NOC] Tôi có nên khởi động lại dịch vụ ứng dụng ngay để hạ CPU xuống không?', 'restart, application service, immediately', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-01-seg-6', 'lesson-audio-itops-01', 'owner', 31.5, 39, 'Wait one minute; drain that server from the load balancer first so we preserve a heap dump.', '[SRE] Khoan một phút; hãy rút lưu lượng khỏi máy chủ đó ở bộ cân bằng tải trước để giữ lại bản chụp bộ nhớ heap.', 'drain, load balancer, preserve, heap dump', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-01-seg-7', 'lesson-audio-itops-01', 'owner', 39, 44.9, 'Got it, traffic is drained and the diagnostic snapshot finished writing to storage.', '[NOC] Rõ rồi, lưu lượng đã được chuyển hướng và bản chụp chẩn đoán đã ghi xong vào bộ lưu trữ.', 'diagnostic snapshot, storage', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-01-seg-8', 'lesson-audio-itops-01', 'owner', 44.9, 52, 'Great, now roll back tonight''s release to the previous stable build while I analyze the dump.', '[SRE] Tuyệt, giờ hãy hoàn tác bản phát hành tối nay về bản dựng ổn định trước đó trong lúc tôi phân tích file dump.', 'roll back, release, stable build, analyze', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-01-seg-9', 'lesson-audio-itops-01', 'owner', 52, 58.3, 'Rollback is complete, CPU dropped to twenty percent, and response times are healthy again.', '[NOC] Hoàn tác xong rồi, CPU đã giảm xuống 20% và thời gian phản hồi đã ổn định trở lại.', 'rollback, response times, healthy', 8);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-02', 'owner', 'audio-itops-02', '02. Expired SSL Certificate Outage (IT Ops)', 'Urgent call between a Helpdesk lead and an Infrastructure engineer fixing an expired TLS certificate on the API gateway (~1 min, B1-B2).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-02-seg-1', 'lesson-audio-itops-02', 'owner', 0, 6.7, 'Hello Sarah, customers are calling because browsers show a security warning on our main portal.', '[Helpdesk] Chào Sarah, khách hàng đang gọi báo trình duyệt hiện cảnh báo bảo mật trên cổng thông tin chính.', 'security warning, main portal', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-02-seg-2', 'lesson-audio-itops-02', 'owner', 6.7, 13.8, 'Let me inspect the TLS handshake; oh no, the public SSL certificate expired ten minutes ago.', '[Infra] Để tôi kiểm tra quá trình bắt tay TLS; ôi không, chứng chỉ SSL công khai vừa hết hạn mười phút trước.', 'inspect, TLS handshake, SSL certificate, expired', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-02-seg-3', 'lesson-audio-itops-02', 'owner', 13.8, 18.8, 'I thought our automation script renewed every certificate automatically before expiration.', '[Helpdesk] Tôi tưởng kịch bản tự động hóa của chúng ta gia hạn mọi chứng chỉ trước khi hết hạn chứ.', 'automation script, renewed, expiration', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-02-seg-4', 'lesson-audio-itops-02', 'owner', 18.8, 25.1, 'A recent firewall change blocked the validation challenge, so the renewal job silently failed.', '[Infra] Một thay đổi tường lửa gần đây đã chặn bước xác thực, nên tác vụ gia hạn bị lỗi âm thầm.', 'firewall, validation challenge, silently failed', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-02-seg-5', 'lesson-audio-itops-02', 'owner', 25.1, 30.6, 'How fast can we restore encrypted traffic without disconnecting active mobile users?', '[Helpdesk] Chúng ta có thể khôi phục lưu lượng mã hóa nhanh cỡ nào mà không ngắt kết nối người dùng di động đang hoạt động?', 'restore, encrypted traffic, disconnecting', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-02-seg-6', 'lesson-audio-itops-02', 'owner', 30.6, 37.7, 'I am uploading the renewed certificate and full intermediate chain to the reverse proxy right now.', '[Infra] Tôi đang tải chứng chỉ mới gia hạn cùng chuỗi chứng chỉ trung gian đầy đủ lên reverse proxy ngay đây.', 'intermediate chain, reverse proxy', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-02-seg-7', 'lesson-audio-itops-02', 'owner', 37.7, 43.6, 'Next, I will reload the web server gracefully so existing connections finish cleanly.', '[Infra] Tiếp theo, tôi sẽ nạp lại cấu hình máy chủ web một cách êm ái để các kết nối hiện có hoàn tất trọn vẹn.', 'reload gracefully, existing connections', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-02-seg-8', 'lesson-audio-itops-02', 'owner', 43.6, 50.3, 'The portal is green again, and let us add a thirty day expiry alert immediately.', '[Helpdesk] Cổng thông tin đã xanh trở lại, và chúng ta hãy thêm ngay cảnh báo hết hạn trước 30 ngày nhé.', 'expiry alert, immediately', 7);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-03', 'owner', 'audio-itops-03', '03. Root Disk Full & Log Rotation Fix (IT Ops)', 'Night-shift Linux troubleshooting call resolving a 100% full root partition, open file handles, and automated log rotation (~1 min, B1-B2).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-03-seg-1', 'lesson-audio-itops-03', 'owner', 0, 6.7, 'Hey Kevin, our billing database just stopped accepting writes and triggered a critical disk alert.', '[Monitoring] Chào Kevin, cơ sở dữ liệu thanh toán vừa ngừng nhận dữ liệu ghi và phát cảnh báo đầy ổ đĩa nghiêm trọng.', 'accepting writes, critical disk alert', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-03-seg-2', 'lesson-audio-itops-03', 'owner', 6.7, 12.6, 'I checked disk usage, and the root partition reached one hundred percent capacity.', '[SysAdmin] Tôi vừa kiểm tra dung lượng đĩa, phân vùng root đã chạm ngưỡng 100% sức chứa.', 'disk usage, root partition, capacity', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-03-seg-3', 'lesson-audio-itops-03', 'owner', 12.6, 18.5, 'Did the database grow unexpectedly, or is something else consuming all that space?', '[Monitoring] Do cơ sở dữ liệu phình to bất ngờ, hay có thứ gì khác đang chiếm hết dung lượng đó?', 'unexpectedly, consuming', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-03-seg-4', 'lesson-audio-itops-03', 'owner', 18.5, 24.4, 'Someone left verbose debug logging enabled, creating a single forty gigabyte text file.', '[SysAdmin] Có ai đó quên tắt chế độ ghi log gỡ lỗi chi tiết, tạo ra một tệp văn bản duy nhất nặng 40 gigabyte.', 'verbose debug logging, enabled', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-03-seg-5', 'lesson-audio-itops-03', 'owner', 24.4, 30.3, 'Can we just delete that huge log file right away to recover storage?', '[Monitoring] Chúng ta có thể xóa thẳng tệp log khổng lồ đó ngay lập tức để lấy lại dung lượng không?', 'recover storage', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-03-seg-6', 'lesson-audio-itops-03', 'owner', 30.3, 37.4, 'Deleting an open file will not free disk space while the running service holds its handle.', '[SysAdmin] Xóa một tệp đang mở sẽ không giải phóng dung lượng đĩa khi dịch vụ đang chạy vẫn giữ bộ mô tả tệp đó.', 'free disk space, holds its handle', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-03-seg-7', 'lesson-audio-itops-03', 'owner', 37.4, 43.7, 'Instead, I will truncate the active file safely and disable verbose logging in configuration.', '[SysAdmin] Thay vào đó, tôi sẽ cắt rỗng tệp đang mở một cách an toàn và tắt log gỡ lỗi chi tiết trong cấu hình.', 'truncate, active file, configuration', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-03-seg-8', 'lesson-audio-itops-03', 'owner', 43.7, 50, 'Database writes resumed immediately; tomorrow let us enforce daily log rotation with automatic compression.', '[Monitoring] Ghi dữ liệu vào database đã chạy lại ngay; ngày mai chúng ta nhớ áp dụng xoay vòng log hằng ngày kèm nén tự động nhé.', 'resumed, enforce, log rotation, compression', 7);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-04', 'owner', 'audio-itops-04', '04. Slow Queries & Database Connection Pool (IT Ops)', 'Incident call between Application Support and a DBA diagnosing checkout timeouts, full table scans, and read replicas (~1 min, B1-B2).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-04-seg-1', 'lesson-audio-itops-04', 'owner', 0, 6.7, 'Hi Priya, checkout requests are timing out and the application logs show connection pool exhaustion.', '[App Support] Chào Priya, các yêu cầu thanh toán đang bị quá thời gian và log ứng dụng báo cạn kiệt bể kết nối.', 'timing out, connection pool exhaustion', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-04-seg-2', 'lesson-audio-itops-04', 'owner', 6.7, 13.8, 'I see dozens of queued queries waiting because a heavy analytics report is locking shared resources.', '[DBA] Tôi thấy hàng chục truy vấn đang xếp hàng chờ vì một báo cáo phân tích nặng đang chiếm dụng tài nguyên dùng chung.', 'queued queries, analytics report, shared resources', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-04-seg-3', 'lesson-audio-itops-04', 'owner', 13.8, 18.8, 'Why is that report taking almost forty seconds to finish today?', '[App Support] Tại sao hôm nay báo cáo đó lại mất gần bốn mươi giây mới chạy xong vậy?', 'almost forty seconds', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-04-seg-4', 'lesson-audio-itops-04', 'owner', 18.8, 25.5, 'The execution plan reveals a full table scan across five million rows without an index.', '[DBA] Kế hoạch thực thi cho thấy đang xảy ra quét toàn bộ bảng qua năm triệu dòng vì thiếu chỉ mục.', 'execution plan, full table scan, index', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-04-seg-5', 'lesson-audio-itops-04', 'owner', 25.5, 31, 'Can we cancel the stuck reporting queries first so checkout traffic recovers?', '[App Support] Mình hủy các truy vấn báo cáo bị treo trước để lưu lượng thanh toán phục hồi được không?', 'cancel, stuck, recovers', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-04-seg-6', 'lesson-audio-itops-04', 'owner', 31, 38.1, 'Done, active connections just dropped by half, and I am routing reports to the read replica.', '[DBA] Xong rồi, số kết nối đang mở vừa giảm một nửa, và tôi đang định tuyến các báo cáo sang bản sao chỉ đọc.', 'routing, read replica', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-04-seg-7', 'lesson-audio-itops-04', 'owner', 38.1, 43.6, 'Should we add the missing composite index during off peak hours tonight?', '[App Support] Chúng ta có nên thêm chỉ mục kết hợp còn thiếu vào giờ thấp điểm tối nay không?', 'composite index, off peak hours', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-04-seg-8', 'lesson-audio-itops-04', 'owner', 43.6, 49.1, 'Even better, we can build it online concurrently without blocking production writes.', '[DBA] Tốt hơn nữa, ta có thể tạo chỉ mục trực tuyến song song mà không làm nghẽn thao tác ghi trên production.', 'concurrently, blocking, production writes', 7);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-05', 'owner', 'audio-itops-05', '05. Load Balancer Health Checks & DNS Failover (IT Ops)', 'Bridge call between Network Ops and a Cloud engineer coordinating multi-zone failover, draining unhealthy targets, and DNS TTL caching (~1 min, B1-B2).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-05-seg-1', 'lesson-audio-itops-05', 'owner', 0, 5.9, 'David, synthetic monitors report intermittent errors from European users after our regional switch.', '[NetOps] David ơi, hệ thống giám sát giả lập báo lỗi chập chờn từ người dùng châu Âu sau khi ta chuyển vùng.', 'synthetic monitors, intermittent errors, regional switch', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-05-seg-2', 'lesson-audio-itops-05', 'owner', 5.9, 12.6, 'Let me check the load balancer; two backend nodes are still failing HTTP health checks.', '[Cloud] Để tôi kiểm tra bộ cân bằng tải; hai máy chủ backend vẫn đang trượt kiểm tra sức khỏe HTTP.', 'backend nodes, HTTP health checks', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-05-seg-3', 'lesson-audio-itops-05', 'owner', 12.6, 17.6, 'Why did the balancer keep sending requests to those unhealthy instances?', '[NetOps] Tại sao bộ cân bằng tải vẫn tiếp tục gửi yêu cầu tới các máy chủ không khỏe mạnh đó?', 'unhealthy instances', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-05-seg-4', 'lesson-audio-itops-05', 'owner', 17.6, 24.7, 'The failure threshold was set too high, so it waited nearly three minutes before draining them.', '[Cloud] Ngưỡng báo lỗi bị đặt quá cao, nên nó chờ gần ba phút mới rút lưu lượng khỏi chúng.', 'failure threshold, draining', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-05-seg-5', 'lesson-audio-itops-05', 'owner', 24.7, 31.8, 'I just tightened the health probe interval and shifted all traffic to our healthy availability zone.', '[Cloud] Tôi vừa siết ngắn chu kỳ thăm dò sức khỏe và chuyển toàn bộ lưu lượng sang vùng sẵn sàng đang ổn định.', 'health probe interval, availability zone', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-05-seg-6', 'lesson-audio-itops-05', 'owner', 31.8, 38.1, 'Some offices still see old IP addresses; is DNS caching slowing down the failover?', '[NetOps] Một số văn phòng vẫn thấy địa chỉ IP cũ; có phải bộ nhớ đệm DNS đang làm chậm quá trình chuyển đổi dự phòng không?', 'DNS caching, failover', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-05-seg-7', 'lesson-audio-itops-05', 'owner', 38.1, 45.2, 'Exactly, our DNS record had a long TTL, so external resolvers are still holding stale entries.', '[Cloud] Chính xác, bản ghi DNS của mình đặt thời gian sống TTL quá dài nên các máy chủ phân giải ngoài vẫn giữ bản ghi cũ.', 'DNS record, resolvers, stale entries', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-05-seg-8', 'lesson-audio-itops-05', 'owner', 45.2, 51.9, 'Once propagation settles, let us lower the TTL to sixty seconds for faster future failovers.', '[NetOps] Khi việc lan truyền DNS ổn định, hãy hạ TTL xuống 60 giây để các lần chuyển đổi dự phòng sau nhanh hơn nhé.', 'propagation settles, lower the TTL', 7);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-06', 'owner', 'audio-itops-06', '06. Kubernetes Pod Crash Loop & Rollback (IT Ops)', 'Release call between a Release Manager and DevOps engineer diagnosing CrashLoopBackOff, OOM kills, ConfigMap errors, and instant rollback (~1 min, B1-B2).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-06-seg-1', 'lesson-audio-itops-06', 'owner', 0, 6.7, 'Elena, right after deploying the payment microservice, every new Kubernetes pod entered a crash loop.', '[Release] Elena ơi, ngay sau khi triển khai microservice thanh toán, mọi pod Kubernetes mới đều rơi vào vòng lặp sập nguồn.', 'deploying, microservice, crash loop', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-06-seg-2', 'lesson-audio-itops-06', 'owner', 6.7, 12.6, 'Hold the rollout immediately; are existing stable pods still serving live customer traffic?', '[DevOps] Tạm dừng triển khai ngay; các pod ổn định cũ có còn đang phục vụ lưu lượng khách hàng thực không?', 'rollout, serving live traffic', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-06-seg-3', 'lesson-audio-itops-06', 'owner', 12.6, 19.7, 'Yes, the readiness probe kept failed containers out of service, so users have not noticed yet.', '[Release] Có, kiểm tra sẵn sàng đã giữ các container lỗi đứng ngoài dịch vụ nên người dùng vẫn chưa bị ảnh hưởng.', 'readiness probe, containers', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-06-seg-4', 'lesson-audio-itops-06', 'owner', 19.7, 26.4, 'I am inspecting the container logs and pod events to find the exact exit code.', '[DevOps] Tôi đang kiểm tra log container và sự kiện của pod để tìm mã thoát chính xác.', 'container logs, pod events, exit code', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-06-seg-5', 'lesson-audio-itops-06', 'owner', 26.4, 32.3, 'Is it hitting the memory limit and getting terminated as out of memory?', '[Release] Có phải nó chạm giới hạn bộ nhớ và bị hệ thống dừng do tràn bộ nhớ không?', 'memory limit, terminated, out of memory', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-06-seg-6', 'lesson-audio-itops-06', 'owner', 32.3, 40.3, 'No, memory looks fine; the container crashed because a required API key is missing from the config map.', '[DevOps] Không, bộ nhớ vẫn ổn; container bị sập vì thiếu một khóa API bắt buộc trong ConfigMap.', 'required API key, config map', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-06-seg-7', 'lesson-audio-itops-06', 'owner', 40.3, 46.6, 'Let us trigger a deployment rollback now to clear the failed replica set cleanly.', '[Release] Hãy kích hoạt hoàn tác triển khai ngay để dọn sạch bộ replica bị lỗi một cách gọn gàng.', 'deployment rollback, replica set', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-06-seg-8', 'lesson-audio-itops-06', 'owner', 46.6, 52.5, 'Rollback succeeded, all replicas are running, and cluster error rates remain completely flat.', '[DevOps] Hoàn tác thành công, mọi bản sao đều đang chạy và tỷ lệ lỗi cụm hoàn toàn bằng phẳng.', 'replicas, cluster error rates', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-06-seg-9', 'lesson-audio-itops-06', 'owner', 52.5, 58.4, 'Before retrying tomorrow, let us add automated configuration validation inside our deployment pipeline.', '[Release] Trước khi thử lại vào ngày mai, hãy thêm bước kiểm tra cấu hình tự động trong quy trình triển khai nhé.', 'configuration validation, deployment pipeline', 8);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-07', 'owner', 'audio-itops-07', '07. Backup Verification & Disaster Recovery Drill (IT Ops)', 'Operations review between an Ops Manager and Backup Admin discussing RTO, RPO, point-in-time recovery, and immutable offsite backups (~1 min, B1-B2).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-07-seg-1', 'lesson-audio-itops-07', 'owner', 0, 7.5, 'Good morning Tom, our compliance audit starts next week; are our disaster recovery metrics up to date?', '[Ops Manager] Chào buổi sáng Tom, đợt kiểm toán tuân thủ bắt đầu tuần tới; các chỉ số phục hồi sau thảm họa của ta đã cập nhật chưa?', 'compliance audit, disaster recovery metrics', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-07-seg-2', 'lesson-audio-itops-07', 'owner', 7.5, 13.8, 'Yes, we take full snapshots every Sunday and run incremental backups every single hour.', '[Backup Admin] Rồi ạ, chúng ta chụp bản sao lưu đầy đủ mỗi Chủ nhật và chạy sao lưu gia tăng mỗi giờ.', 'full snapshots, incremental backups', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-07-seg-3', 'lesson-audio-itops-07', 'owner', 13.8, 20.5, 'That keeps our recovery point objective under one hour, but what about actual restore speed?', '[Ops Manager] Như vậy giữ mục tiêu điểm phục hồi RPO dưới một giờ, nhưng tốc độ khôi phục thực tế thì sao?', 'recovery point objective, restore speed', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-07-seg-4', 'lesson-audio-itops-07', 'owner', 20.5, 26.8, 'We ran an automated restore drill in staging yesterday and verified full database integrity.', '[Backup Admin] Hôm qua tụi em đã chạy diễn tập khôi phục tự động trên môi trường staging và kiểm chứng toàn vẹn dữ liệu.', 'restore drill, staging, database integrity', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-07-seg-5', 'lesson-audio-itops-07', 'owner', 26.8, 33.1, 'How long did the entire point in time recovery take from start to finish?', '[Ops Manager] Toàn bộ quá trình khôi phục về đúng thời điểm mất bao lâu từ đầu đến cuối?', 'point in time recovery', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-07-seg-6', 'lesson-audio-itops-07', 'owner', 33.1, 39, 'Thirty five minutes total, comfortably beating our two hour recovery time objective target.', '[Backup Admin] Tổng cộng 35 phút, vượt xa mục tiêu thời gian phục hồi RTO hai giờ của chúng ta.', 'comfortably beating, recovery time objective', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-07-seg-7', 'lesson-audio-itops-07', 'owner', 39, 44.9, 'Are offsite copies stored in an immutable bucket to protect against ransomware attacks?', '[Ops Manager] Các bản sao lưu ngoài site có được lưu trong kho bất biến để chống lại tấn công mã độc tống tiền không?', 'offsite copies, immutable bucket, ransomware', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-07-seg-8', 'lesson-audio-itops-07', 'owner', 44.9, 51.6, 'Absolutely, object lock prevents any modification or deletion for ninety days, even with admin credentials.', '[Backup Admin] Chắc chắn rồi, khóa đối tượng ngăn mọi chỉnh sửa hay xóa bỏ trong 90 ngày, kể cả với quyền quản trị.', 'object lock, modification, admin credentials', 7);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-08', 'owner', 'audio-itops-08', '08. Suspicious SSH Login & Firewall Hardening (IT Ops)', 'Security escalation call between a SOC analyst and a SysOps engineer blocking SSH brute-force attacks and hardening bastion access (~1 min, B1-B2).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-08-seg-1', 'lesson-audio-itops-08', 'owner', 0, 7.5, 'Hi Leo, our intrusion detection system just flagged thousands of failed SSH logins on edge server two.', '[SOC] Chào Leo, hệ thống phát hiện xâm nhập vừa gắn cờ hàng nghìn lượt đăng nhập SSH thất bại trên máy chủ biên số hai.', 'intrusion detection, flagged, SSH logins', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-08-seg-2', 'lesson-audio-itops-08', 'owner', 7.5, 13.4, 'Thanks for escalating quickly; did any unauthorized account actually succeed in logging in?', '[SysOps] Cảm ơn đã báo leo thang sớm; có tài khoản trái phép nào thực sự đăng nhập thành công không?', 'escalating, unauthorized account', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-08-seg-3', 'lesson-audio-itops-08', 'owner', 13.4, 20.9, 'No interactive sessions opened yet, though the traffic comes from a coordinated range of foreign IP addresses.', '[SOC] Chưa có phiên tương tác nào được mở, nhưng lưu lượng đến từ một dải địa chỉ IP nước ngoài có phối hợp.', 'interactive sessions, coordinated range', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-08-seg-4', 'lesson-audio-itops-08', 'owner', 20.9, 27.6, 'I am adding an immediate deny rule at the perimeter firewall to block those subnets.', '[SysOps] Tôi đang thêm quy tắc chặn ngay lập tức trên tường lửa vòng ngoài để khóa các dải mạng con đó.', 'deny rule, perimeter firewall, subnets', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-08-seg-5', 'lesson-audio-itops-08', 'owner', 27.6, 34.3, 'Why was the SSH port exposed directly to the public internet in the first place?', '[SOC] Ngay từ đầu tại sao cổng SSH lại bị mở trực tiếp ra internet công cộng vậy?', 'exposed directly, public internet', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-08-seg-6', 'lesson-audio-itops-08', 'owner', 34.3, 41.4, 'A contractor opened it briefly during migration and forgot to restrict access to our bastion host.', '[SysOps] Một nhà thầu đã mở tạm lúc di chuyển hệ thống và quên giới hạn truy cập chỉ qua máy chủ trung gian bastion.', 'contractor, migration, bastion host', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-08-seg-7', 'lesson-audio-itops-08', 'owner', 41.4, 47.3, 'Please disable password authentication completely so only hardware backed SSH keys are accepted.', '[SOC] Vui lòng tắt hoàn toàn xác thực bằng mật khẩu để chỉ chấp nhận khóa SSH có bảo vệ phần cứng.', 'disable password authentication, SSH keys', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-08-seg-8', 'lesson-audio-itops-08', 'owner', 47.3, 54, 'Done, firewall rules are locked down, service credentials are rotated, and audit logs are archived.', '[SysOps] Xong rồi, quy tắc tường lửa đã khóa chặt, thông tin xác thực dịch vụ đã xoay mới và nhật ký kiểm toán đã được lưu trữ.', 'locked down, credentials rotated, audit logs', 7);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-09', 'owner', 'audio-itops-09', '09. Maintenance Window & Kernel Patching (IT Ops)', 'Change Advisory Board call coordinating a low-risk Linux kernel security patch with snapshots, rolling updates, and smoke tests (~1 min, B1-B2).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-09-seg-1', 'lesson-audio-itops-09', 'owner', 0, 6.7, 'Thanks for joining the change advisory call; let us review Sunday''s Linux kernel security patching.', '[Change Mgr] Cảm ơn đã tham gia cuộc họp hội đồng quản lý thay đổi; cùng rà soát đợt vá bảo mật nhân Linux Chủ nhật này nhé.', 'change advisory, kernel security patching', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-09-seg-2', 'lesson-audio-itops-09', 'owner', 6.7, 13.4, 'We scheduled the maintenance window for two in the morning when customer traffic is lowest.', '[SysEng] Chúng tôi lên lịch khung thời gian bảo trì lúc hai giờ sáng khi lưu lượng khách hàng thấp nhất.', 'maintenance window, lowest', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-09-seg-3', 'lesson-audio-itops-09', 'owner', 13.4, 18, 'Will customers experience full downtime while the application servers reboot?', '[Change Mgr] Khách hàng có gặp tình trạng gián đoạn hoàn toàn trong lúc các máy chủ ứng dụng khởi động lại không?', 'full downtime, reboot', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-09-seg-4', 'lesson-audio-itops-09', 'owner', 18, 24.7, 'No, we will perform rolling updates one node at a time across our redundant cluster.', '[SysEng] Không ạ, ta sẽ cập nhật cuốn chiếu từng máy chủ một trong cụm dự phòng.', 'rolling updates, redundant cluster', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-09-seg-5', 'lesson-audio-itops-09', 'owner', 24.7, 30.6, 'Before applying any patches, make sure fresh system snapshots are captured and verified.', '[Change Mgr] Trước khi cài bất kỳ bản vá nào, hãy đảm bảo các bản chụp hệ thống mới đã được tạo và kiểm tra.', 'patches, system snapshots, verified', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-09-seg-6', 'lesson-audio-itops-09', 'owner', 30.6, 37.3, 'Agreed, and if automated smoke tests fail on node one, we abort immediately and revert.', '[SysEng] Nhất trí, và nếu kiểm thử nhanh tự động trên node một thất bại, ta hủy ngay lập tức và khôi phục lại.', 'smoke tests, abort, revert', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-09-seg-7', 'lesson-audio-itops-09', 'owner', 37.3, 43.2, 'Has customer support already published the advance notice on our public status page?', '[Change Mgr] Bộ phận hỗ trợ khách hàng đã đăng thông báo trước lên trang trạng thái công khai chưa?', 'advance notice, status page', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-09-seg-8', 'lesson-audio-itops-09', 'owner', 43.2, 49.5, 'Yes, subscribers received email alerts yesterday, and the on call roster is confirmed ready.', '[SysEng] Rồi ạ, người đăng ký đã nhận email thông báo hôm qua và lịch trực ứng cứu đã xác nhận sẵn sàng.', 'subscribers, on call roster, confirmed', 7);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-10', 'owner', 'audio-itops-10', '10. Blameless Postmortem & SLA Review (IT Ops)', 'Post-incident review between an SRE Lead and Operations Engineer covering root cause analysis, SLA error budgets, alert fatigue, and runbooks (~1 min, B1-B2).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-10-seg-1', 'lesson-audio-itops-10', 'owner', 0, 5.9, 'Thanks everyone for joining this blameless postmortem for Tuesday''s priority one gateway outage.', '[SRE Lead] Cảm ơn mọi người đã tham gia buổi phân tích sau sự cố không đổ lỗi cho sự cố cổng ưu tiên cấp một hôm thứ Ba.', 'blameless postmortem, priority one outage', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-10-seg-2', 'lesson-audio-itops-10', 'owner', 5.9, 11.8, 'Remember our goal is strengthening system reliability rather than blaming any individual engineer.', '[SRE Lead] Hãy nhớ mục tiêu của ta là củng cố độ tin cậy hệ thống chứ không phải đổ lỗi cho bất kỳ kỹ sư cá nhân nào.', 'strengthening, reliability, individual', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-10-seg-3', 'lesson-audio-itops-10', 'owner', 11.8, 17.7, 'Our timeline shows twenty two minutes of partial degradation before automated failover engaged.', '[Ops Eng] Dòng thời gian ghi nhận 22 phút suy giảm hiệu năng một phần trước khi chuyển đổi dự phòng tự động kích hoạt.', 'timeline, partial degradation, engaged', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-10-seg-4', 'lesson-audio-itops-10', 'owner', 17.7, 23.2, 'Did that outage breach our monthly service level agreement with enterprise clients?', '[SRE Lead] Sự cố đó có làm vi phạm cam kết mức độ dịch vụ SLA hằng tháng với khách hàng doanh nghiệp không?', 'breach, service level agreement', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-10-seg-5', 'lesson-audio-itops-10', 'owner', 23.2, 29.9, 'Fortunately no, we stayed within SLA, though we consumed half of this quarter''s error budget.', '[Ops Eng] May mắn là không, ta vẫn nằm trong SLA, dù đã tiêu hết một nửa ngân sách lỗi của quý này.', 'consumed, error budget', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-10-seg-6', 'lesson-audio-itops-10', 'owner', 29.9, 34.9, 'What was the main contributing factor behind our delayed initial response?', '[SRE Lead] Đâu là yếu tố góp phần chính dẫn đến việc phản hồi ban đầu bị chậm trễ?', 'contributing factor, initial response', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-10-seg-7', 'lesson-audio-itops-10', 'owner', 34.9, 41.6, 'Severe alert fatigue; noisy low priority warnings buried the critical page in our incident channel.', '[Ops Eng] Sự quá tải cảnh báo nghiêm trọng; các cảnh báo mức thấp ồn ào đã che lấp thông báo khẩn cấp trong kênh sự cố.', 'alert fatigue, noisy warnings, buried', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-10-seg-8', 'lesson-audio-itops-10', 'owner', 41.6, 48.3, 'Let us silence non actionable alerts and update the incident runbook with clearer escalation steps.', '[SRE Lead] Hãy tắt các cảnh báo không thể hành động và cập nhật sổ tay xử lý sự cố với các bước leo thang rõ ràng hơn.', 'non actionable, incident runbook, escalation steps', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-10-seg-9', 'lesson-audio-itops-10', 'owner', 48.3, 55, 'I already created tracked tickets with owners and deadlines so every preventive action gets completed.', '[Ops Eng] Tôi đã tạo sẵn các phiếu công việc có người phụ trách và hạn chót để mọi biện pháp phòng ngừa đều được hoàn tất.', 'tracked tickets, preventive action', 8);
